\begin{lemma}[The Poincaré Lemma]
\label{lem:poincare-lemma}
\dcref{chB:B.14}
[LeeSM, Thm. 17.14] If $U$ is a star-shaped open subset of $\mathbb{R}^n$, then for $k \geq 1$, every closed $k$-form on $U$ is exact.
\end{lemma}

